/* rootclock -- IconStore: the 13 faction icons as RGB565 arrays in flash.
 *
 * faction_icons.c is GENERATED by apps/rootclock/tools/gen_faction_icons.py
 * from apps/rootclock/assets/factions/<key>.png and checked in, so the build
 * never needs Pillow. Each icon is cropped to its alpha bounding box, fitted
 * inside RC_ICON_W x RC_ICON_H keeping its aspect ratio, centred and
 * composited onto the UI_TILE colour (#EDE3C8), then packed like
 * st7789_rgb565(). Order is rc_faction_id_t. */
#ifndef FACTION_ICONS_H
#define FACTION_ICONS_H
#include <stdint.h>

#define RC_ICON_W 96u
#define RC_ICON_H 96u

typedef struct {
    uint16_t        w, h;   /* RC_ICON_W x RC_ICON_H for a real icon        */
    const uint16_t *px;     /* row-major, w*h native-endian RGB565 values;
                               NULL only in the pre-generation stub, in which
                               case a renderer fills the tile with UI_TILE  */
} rc_icon_t;

/* Never NULL. An out-of-range id returns an icon with px == NULL. Blit with
 * st7789_set_window(x, y, w, h) + st7789_blit(px, w * h). */
const rc_icon_t *rc_icon_get(uint8_t faction_id);

#endif
